package com.proofclean.analysis.controller;
import com.proofclean.analysis.repository.*;import com.proofclean.common.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.nio.file.Path;
@RestController @RequestMapping("/api/files") @RequiredArgsConstructor
public class FileController { private final UploadedFileRepository uploadedFileRepository; private final MaskedFileRepository maskedFileRepository; @GetMapping("/{fileId}/preview") public ResponseEntity<Resource> preview(Authentication a,@PathVariable Long fileId){ var f=uploadedFileRepository.findById(fileId).orElseThrow(()->new NotFoundException("파일을 찾을 수 없습니다.")); if(!f.getAnalysisProject().getUser().getEmail().equals(a.getName())) throw new ForbiddenException("접근 권한이 없습니다."); return ResponseEntity.ok().contentType(MediaType.parseMediaType(f.getMimeType())).body(new FileSystemResource(Path.of(f.getFilePath()))); } @GetMapping("/masked/{id}/preview") public ResponseEntity<Resource> maskedPreview(Authentication a,@PathVariable Long id){ var f=maskedFileRepository.findById(id).orElseThrow(()->new NotFoundException("안전본을 찾을 수 없습니다.")); if(!f.getAnalysisProject().getUser().getEmail().equals(a.getName())) throw new ForbiddenException("접근 권한이 없습니다."); return ResponseEntity.ok().contentType(MediaType.IMAGE_PNG).body(new FileSystemResource(Path.of(f.getMaskedFilePath()))); } @GetMapping("/masked/{id}/download") public ResponseEntity<Resource> download(Authentication a,@PathVariable Long id){ var f=maskedFileRepository.findById(id).orElseThrow(()->new NotFoundException("안전본을 찾을 수 없습니다.")); if(!f.getAnalysisProject().getUser().getEmail().equals(a.getName())) throw new ForbiddenException("접근 권한이 없습니다."); return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+f.getMaskedFileName()+"\"").contentType(MediaType.APPLICATION_OCTET_STREAM).body(new FileSystemResource(Path.of(f.getMaskedFilePath()))); } }
